138	      productTypeCreate(input: $input) { productType { id } errors { field code message } }
139	    }`,
140	    {
141	      input: { name: "E2E Simple", kind: "NORMAL", hasVariants: false, isShippingRequired: true },
142	    },
143	  );
144	  const variantIds: Record<keyof typeof PRODUCTS, string> = { tee: "", hoodie: "" };
145	
146	  for (const [key, product] of Object.entries(PRODUCTS) as [
147	    keyof typeof PRODUCTS,
148	    (typeof PRODUCTS)[keyof typeof PRODUCTS],
149	  ][]) {
150	    const created = await mutate<{ product: { id: string } }>(
151	      "productCreate",
152	      `mutation($input: ProductCreateInput!) {
153	        productCreate(input: $input) { product { id } errors { field code message } }
154	      }`,
155	      { input: { name: product.name, productType: productType.id, category: shop.categoryId } },
156	    );
157	    const { productVariant } = await mutate<{ productVariant: { id: string } }>(
158	      "productVariantCreate",
159	      `mutation($input: ProductVariantCreateInput!) {
160	        productVariantCreate(input: $input) { productVariant { id } errors { field code message } }
161	      }`,
162	      {
163	        input: {
164	          product: created.product.id,
165	          sku: product.sku,
166	          attributes: [],
167	          trackInventory: true,
168	          stocks: [{ warehouse: shop.warehouseId, quantity: 1000 }],
169	        },
170	      },
171	    );
172	
173	    await mutate(
174	      "productChannelListingUpdate",
175	      `mutation($id: ID!, $input: ProductChannelListingUpdateInput!) {
176	        productChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
177	      }`,
178	      {
179	        id: created.product.id,
180	        input: {
181	          updateChannels: [
182	            {
183	              channelId: shop.channelId,
184	              isPublished: true,
185	              visibleInListings: true,
186	              isAvailableForPurchase: true,
187	              addVariants: [productVariant.id],
188	            },
189	          ],
190	        },
191	      },
192	    );
193	    await mutate(
194	      "productVariantChannelListingUpdate",
195	      `mutation($id: ID!, $input: [ProductVariantChannelListingAddInput!]!) {
196	        productVariantChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
197	      }`,
198	      {
199	        id: productVariant.id,
200	        input: [{ channelId: shop.channelId, price: product.price }],
201	      },
202	    );
203	
204	    variantIds[key] = productVariant.id;
205	  }
206	
207	  return variantIds;
208	};
