1	import fs from "node:fs";
2	import path from "node:path";
3	
4	import type { E2eConfig } from "../config.ts";
5	import { type Actor, credentialsFor } from "./actors.ts";
6	import { imageId } from "./docker.ts";
7	import { signIn } from "./graphql.ts";
8	import { cacheDir } from "./seed.ts";
9	
10	/**
11	 * A signed-in browser state for an actor.
12	 *
13	 * The dashboard reads its refresh token from `localStorage._saleorRefreshToken` on start
14	 * (see `src/auth/tokenStorage.ts`, which names this a public contract), so a session is
15	 * just that one entry - no UI login, no cookies to carry.
16	 *
17	 * States live under the same image-keyed cache as the seed dumps. That matters: a restored
18	 * scenario brings the *same* user rows back, so a token survives a per-test reset, but a
19	 * dump rebuilt from a new Saleor image brings different ones, and a stale token would then
20	 * fail in a way that looks like a dashboard bug. Sharing the cache key retires both at once.
21	 */
22	export const storageStatePath = (config: E2eConfig, actor: Actor) =>
23	  path.join(cacheDir(config, imageId(config)), "auth", `${actor}.json`);
24	
25	export const writeStorageState = async (config: E2eConfig, actor: Actor) => {
26	  const target = storageStatePath(config, actor);
27	
28	  if (fs.existsSync(target)) {
29	    return target;
30	  }
31	
32	  const { email, password } = credentialsFor(actor);
33	  const { refreshToken } = await signIn(config, email, password);
34	
35	  fs.mkdirSync(path.dirname(target), { recursive: true });
36	  fs.writeFileSync(
37	    target,
38	    JSON.stringify(
39	      {
40	        cookies: [],
41	        origins: [
42	          {
43	            origin: new URL(config.dashboardUrl).origin,
44	            localStorage: [{ name: "_saleorRefreshToken", value: refreshToken }],
45	          },
46	        ],
47	      },
48	      null,
49	      2,
50	    ),
51	  );
52	
53	  return target;
54	};
