784	                    onPaste
785	                    isOutsideClick={isMacawPortalOutsideClick}
786	                    rightElementProps={{
787	                      sticky: true,
788	                    }}
789	                    rightElement={
790	                      <div
791	                        className={clsx(classes.rowActionBar, {
792	                          [classes.rowActionBarScrolledToRight]: scrolledToRight,
793	                          [classes.rowActionvBarWithItems]: hasMenuItem,
794	                        })}
795	                        style={{ width: rowActionBarWidth }}
796	                      >
