834	                </div>
835	              </>
836	            ) : (
837	              <Box paddingX={6} paddingTop={renderHeader ? 5 : undefined} paddingBottom={6}>
838	                {emptyState ?? (
839	                  <Placeholder>
840	                    <span data-test-id="empty-data-grid-text">{emptyText}</span>
841	                  </Placeholder>
842	                )}
843	              </Box>
844	            )}
845	          </DashboardCard.Content>
846	        </DashboardCard>
847	        <TooltipContainer
848	          key={tooltip ? `${tooltip.location[0]}-${tooltip.location[1]}` : undefined}
849	          bounds={tooltip?.bounds}
850	          content={tooltip?.content}
851	          side={tooltip?.side}
852	          align={tooltip?.align}
853	        />
854	        {rowAnchor && (
855	          <a
856	            ref={setRowAnchorRef}
857	            className={classes.rowAnchor}
858	            data-test-id="datagrid-row-anchor"
859	            tabIndex={-1}
860	            aria-hidden={true}
861	            onClick={rowAnchorHandler}
862	            // Only the overlay. Capture on PreventHistoryBack would also swallow
863	            // header, column-picker, and row-action clicks after a 6px slop.
864	            onClickCapture={onClickCapture}
865	          />
866	        )}
867	      </PreventHistoryBack>
868	    </FullScreenContainer>
869	  );
870	};
